public void initValue()
{
    super();

    this.ConsentSms      = UTCSFMarketingConsent::NotCaptured;
    this.ConsentWhatsApp = UTCSFMarketingConsent::NotCaptured;
    this.ConsentEmail    = UTCSFMarketingConsent::NotCaptured;
    this.IsSynced        = NoYes::No;
}

public void insert()
{
    boolean hasExplicitConsent = (this.ConsentSms      != UTCSFMarketingConsent::NotCaptured
                               || this.ConsentWhatsApp != UTCSFMarketingConsent::NotCaptured
                               || this.ConsentEmail    != UTCSFMarketingConsent::NotCaptured);

    if (hasExplicitConsent && this.ConsentCapturedDateTime == DateTimeUtil::minValue())
    {
        this.ConsentCapturedDateTime = DateTimeUtil::utcNow();
    }

    super();

    if (hasExplicitConsent && this.CustAccount)
    {
        UTCSFCustomerChangeHandler::tryEnqueueByCustAccount(this.CustAccount);
    }
}

public void update()
{
    UTCSFCustomerState origState = this.orig();

    boolean hasConsentChange = (this.ConsentSms      != origState.ConsentSms
                             || this.ConsentWhatsApp != origState.ConsentWhatsApp
                             || this.ConsentEmail    != origState.ConsentEmail);

    if (hasConsentChange)
    {
        // Salesforce v1.6 ignores consent updates without a newer ConsentCapturedDateTime
        if (this.ConsentCapturedDateTime <= origState.ConsentCapturedDateTime)
        {
            this.ConsentCapturedDateTime = DateTimeUtil::utcNow();
            if (this.ConsentCapturedDateTime <= origState.ConsentCapturedDateTime)
            {
                this.ConsentCapturedDateTime = DateTimeUtil::addSeconds(origState.ConsentCapturedDateTime, 1);
            }
        }
    }

    super();

    if (hasConsentChange && this.CustAccount)
    {
        UTCSFCustomerChangeHandler::tryEnqueueByCustAccount(this.CustAccount);
    }
}

public static UTCSFCustomerState find(CustAccount _custAccount, boolean _forUpdate = false)
{
    UTCSFCustomerState stateRecord;

    if (_custAccount)
    {
        stateRecord.selectForUpdate(_forUpdate);

        select firstonly stateRecord
            index CustAccountIdx
            where stateRecord.CustAccount == _custAccount;
    }

    return stateRecord;
}

/// <summary>
/// Returns true if the customer has previously been synced to Salesforce (either tracked in
/// <c>UTCSFCustomerState</c> or recorded in <c>UTCSFCustomerPushQueue</c> prior to v1.6 upgrade).
/// Used to ensure customers moved to out-of-scope groups (e.g. Retail -&gt; Coops) still push updates.
/// </summary>
public static boolean isCustomerSynced(CustAccount _custAccount)
{
    if (!_custAccount)
    {
        return false;
    }

    UTCSFCustomerState stateRecord = UTCSFCustomerState::find(_custAccount);
    if (stateRecord.RecId != 0 && (stateRecord.IsSynced == NoYes::Yes || stateRecord.SalesforceAccountId != ''))
    {
        return true;
    }

    UTCSFCustomerPushQueue priorSucceededQueue;
    select firstonly RecId from priorSucceededQueue
        index CustAccountStatusIdx
        where priorSucceededQueue.CustAccount == _custAccount
           && priorSucceededQueue.Status      == UTCSFCustomerPushStatus::Succeeded
           && priorSucceededQueue.SalesforceAccountId != '';

    return priorSucceededQueue.RecId != 0;
}

/// <summary>
/// Persists the latest Salesforce sync state for a customer without touching <c>CustTable</c>
/// (avoiding <c>CustTable</c> lock contention and <c>UpdateConflict</c> errors on POS/UI saves).
/// </summary>
public static void upsertSyncResult(
    CustAccount              _custAccount,
    DirPartyNumber           _partyNumber,
    CustGroupId              _custGroup,
    UTCSFSalesforceAccountId _sfAccountId,
    UTCSFSalesforceContactId _sfContactId,
    UTCSFRowStatus           _rowStatus)
{
    #OCCRetryCount
    UTCSFCustomerState stateRecord;

    if (!_custAccount)
    {
        return;
    }

    try
    {
        ttsbegin;

        stateRecord = UTCSFCustomerState::find(_custAccount, true);
        if (!stateRecord.RecId)
        {
            stateRecord.clear();
            stateRecord.initValue();
            stateRecord.CustAccount = _custAccount;
        }

        if (_partyNumber)
        {
            stateRecord.PartyNumber = _partyNumber;
        }
        if (_custGroup)
        {
            stateRecord.LastSyncedCustGroup = _custGroup;
        }
        if (_sfAccountId)
        {
            stateRecord.SalesforceAccountId = _sfAccountId;
        }
        if (_sfContactId)
        {
            stateRecord.SalesforcePersonContactId = _sfContactId;
        }

        stateRecord.LastRowStatus      = _rowStatus;
        stateRecord.LastSyncedDateTime = DateTimeUtil::utcNow();

        if (_sfAccountId != ''
            || _rowStatus == 'created'
            || _rowStatus == 'updated'
            || _rowStatus == 'unchanged'
            || _rowStatus == 'matched'
            || _rowStatus == 'merged')
        {
            stateRecord.IsSynced = NoYes::Yes;
        }

        if (stateRecord.RecId)
        {
            stateRecord.update();
        }
        else
        {
            stateRecord.insert();
        }

        ttscommit;
    }
    catch (Exception::DuplicateKeyException)
    {
        if (appl.ttsLevel() == 0 && xSession::currentRetryCount() < #RetryNum)
        {
            retry;
        }
        throw Exception::DuplicateKeyExceptionNotRecovered;
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0 && xSession::currentRetryCount() < #RetryNum)
        {
            retry;
        }
        throw Exception::UpdateConflictNotRecovered;
    }
}

/// <summary>
/// Updates marketing consent flags for a customer, stamps a new <c>ConsentCapturedDateTime</c>,
/// and automatically enqueues an outbound Salesforce v1.6 customer update.
/// </summary>
public static UTCSFCustomerState updateCustomerConsent(
    CustAccount           _custAccount,
    UTCSFMarketingConsent _consentSms,
    UTCSFMarketingConsent _consentWhatsApp,
    UTCSFMarketingConsent _consentEmail,
    utcdatetime           _capturedDateTime = DateTimeUtil::minValue())
{
    UTCSFCustomerState stateRecord;

    if (!_custAccount)
    {
        return stateRecord;
    }

    ttsbegin;

    stateRecord = UTCSFCustomerState::find(_custAccount, true);
    if (!stateRecord.RecId)
    {
        CustTable custTable = CustTable::find(_custAccount);
        DirPartyTable dirParty = DirPartyTable::findRec(custTable.Party);

        stateRecord.clear();
        stateRecord.initValue();
        stateRecord.CustAccount = _custAccount;
        stateRecord.PartyNumber = dirParty.PartyNumber;
    }

    stateRecord.ConsentSms      = _consentSms;
    stateRecord.ConsentWhatsApp = _consentWhatsApp;
    stateRecord.ConsentEmail    = _consentEmail;

    if (_capturedDateTime != DateTimeUtil::minValue())
    {
        stateRecord.ConsentCapturedDateTime = _capturedDateTime;
    }

    if (stateRecord.RecId)
    {
        stateRecord.update();
    }
    else
    {
        stateRecord.insert();
    }

    ttscommit;

    return stateRecord;
}
